CREATE TABLE cmdb_ire_merge_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, source_ci_id BIGINT UNSIGNED NOT NULL, canonical_ci_id BIGINT UNSIGNED NOT NULL, merged_by BIGINT UNSIGNED NOT NULL, reason VARCHAR(1000) NOT NULL, plan JSON NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY cmdb_ire_merge_tenant_id(tenant_id,id), KEY cmdb_ire_merge_canonical(tenant_id,canonical_ci_id,id), CONSTRAINT cmdb_ire_merge_source FOREIGN KEY(tenant_id,source_ci_id) REFERENCES cmdb_cis(tenant_id,id), CONSTRAINT cmdb_ire_merge_canonical FOREIGN KEY(tenant_id,canonical_ci_id) REFERENCES cmdb_cis(tenant_id,id), CONSTRAINT cmdb_ire_merge_user FOREIGN KEY(merged_by) REFERENCES users(id), CONSTRAINT cmdb_ire_merge_distinct CHECK(source_ci_id<>canonical_ci_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
